/* Working C app: recompile through the SDK and print a verified report card. */
#include "gamerecomp_sdk.h"
#include <stdio.h>
#include <string.h>
int main(int argc, char **argv) {
    if (argc != 4) { fprintf(stderr, "usage: app <cli> <pe> <project>\n"); return 2; }
    gr_client c; char report[1024] = {0};
    gr_result r = gr_client_init_ex(&c, argv[1]);
    if (gr_result_code(r) != GR_OK) { fprintf(stderr, "init: %s\n", gr_result_detail(r)); return 1; }
    r = gr_recompile_ex(&c, argv[2], argv[3], report, sizeof report);
    if (gr_result_code(r) != GR_OK) { fprintf(stderr, "recompile: %s\n", gr_result_detail(r)); gr_client_free(&c); return 1; }
    FILE *f = fopen(report, "rb");
    if (!f) { fprintf(stderr, "report missing\n"); gr_client_free(&c); return 1; }
    fseek(f, 0, SEEK_END); long bytes = ftell(f); fclose(f);
    printf("APP_OK sdk=c report=%s bytes=%ld\n", report, bytes);
    gr_client_free(&c);
    return 0;
}

// Working C++ app: RAII client plus parsed score from the SDK report.
#include "gamerecomp_sdk.hpp"
#include <iostream>
int main(int argc, char **argv) {
    if (argc != 4) { std::cerr << "usage: app <cli> <pe> <project>\n"; return 2; }
    try {
        gamerecomp::Client client(argv[1]);
        auto report = client.recompile(argv[2], argv[3]);
        std::cout << "APP_OK sdk=cpp report=" << report.path
                  << " score=" << report.score() << "\n";
    } catch (const std::exception &e) { std::cerr << "error: " << e.what() << "\n"; return 1; }
    return 0;
}

// Working JavaScript app: recompile and print a structured report card.
const { Client } = require('../../../js');
const [cli, pe, project] = process.argv.slice(2);
if (!cli || !pe || !project) {
  console.error('usage: node app.js <cli> <pe> <project>');
  process.exit(2);
}
try {
  const client = new Client(cli);
  const report = client.recompile(pe, project);
  const stages = Array.isArray(report.stages) ? report.stages.length : 0;
  console.log(`APP_OK sdk=javascript score=${report.score ?? 'null'} stages=${stages} report=${client.recompileToPath(pe, project)}`);
} catch (e) { console.error(`error: ${e.message}`); process.exit(1); }

//! Working Rust app: typed report plus raw JSON from the SDK.
use gamerecomp_sdk::Client;
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.len() != 3 { eprintln!("usage: app <cli> <pe> <project>"); std::process::exit(2); }
    let client = match Client::new(&args[0]) { Ok(c) => c, Err(e) => { eprintln!("init: {e}"); std::process::exit(1); } };
    let report = match client.recompile(&args[1], &args[2]) { Ok(r) => r, Err(e) => { eprintln!("recompile: {e}"); std::process::exit(1); } };
    let raw = report.report_json();
    println!("APP_OK sdk=rust score={:?} report={} json_bytes={}", report.score, report.path.display(), raw.len());
}
